def _valid_key(key):
    if not key or not (key[0].isascii() and (key[0].isalpha() or key[0] == "_")):
        return False
    return all(ch.isascii() and (ch.isalnum() or ch == "_") for ch in key)


def parse_profile(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    result = {}
    for number, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError("malformed line " + str(number))
        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip()
        if not _valid_key(key):
            raise ValueError("invalid key on line " + str(number))
        result.setdefault(key, value)
    return result


def profile_is_complete(profile, required_keys):
    if not isinstance(profile, dict):
        raise TypeError("profile must be a dictionary")
    try:
        keys = tuple(required_keys)
    except TypeError as exc:
        raise TypeError("required_keys must be iterable") from exc
    for key in keys:
        if not isinstance(key, str):
            raise TypeError("required keys must be strings")
        if key not in profile:
            return False
        value = profile[key]
        if not isinstance(value, str):
            raise TypeError("profile values must be strings")
        if not value.strip():
            return False
    return True

